// Self-contained lightweight debounce function
function debounce<T extends (...args: any[]) => void>(func: T, wait: number) {
  let timeout: NodeJS.Timeout | null = null;
  const debounced = (...args: Parameters<T>) => {
    if (timeout) clearTimeout(timeout);
    timeout = setTimeout(() => {
      func(...args);
    }, wait);
  };
  debounced.cancel = () => {
    if (timeout) {
      clearTimeout(timeout);
      timeout = null;
    }
  };
  return debounced;
}

// TypeScript interfaces for PDV Module
export interface StaffPin {
  id: string;
  name: string;
  pin: string;
  role: "gerente" | "funcionario" | "caixa" | "vendedor";
  permissions?: string[];
}

export function migrateStaffPinsPermissions(staffList: any[]): StaffPin[] {
  if (!Array.isArray(staffList)) return [];
  const legacyMap: Record<string, string[]> = {
    "consultar_vendas": ["allowDiscount"],
    "alterar_precos": ["allowEditPrice"],
    "gerenciar_estoque": ["allowRemoveProduct"],
    "estornar_vendas": ["allowVoidSale"],
    "sangria_caixa": ["allowSangria", "allowSuprimento"],
    "fechar_turno": ["allowCloseShift", "allowOpenBalance"],
    "consultar_relatorios": ["allowViewReports"],
    "zerar_sistema": ["allowResetEntirePDV"]
  };

  return staffList.map(s => {
    if (!s.permissions || s.permissions.length === 0) return s;
    
    const migratedSet = new Set<string>();
    s.permissions.forEach((p: string) => {
      if (legacyMap[p]) {
        legacyMap[p].forEach(k => migratedSet.add(k));
      } else {
        migratedSet.add(p);
      }
    });
    return {
      ...s,
      permissions: Array.from(migratedSet)
    };
  });
}

export function getStaffPermissions(
  staff: StaffPin,
  systemConfig: SystemConfig | null,
  pdvPermissions: PDVPermissions
): string[] {
  if (staff.permissions && Array.isArray(staff.permissions) && staff.permissions.length > 0) {
    return staff.permissions;
  }

  if (systemConfig) {
    const roleKey = (staff.role === "funcionario" ? "caixa" : staff.role) as "caixa" | "vendedor" | "gerente";
    const roleConfig = systemConfig[roleKey];
    if (roleConfig) {
      const permsList: string[] = [];
      if (roleConfig.allowDiscount) permsList.push("allowDiscount");
      if (roleConfig.allowEditPrice) permsList.push("allowEditPrice");
      if (roleConfig.allowVoidSale) permsList.push("allowVoidSale");
      if (roleConfig.allowSuprimento) permsList.push("allowSuprimento");
      if (roleConfig.allowSangria) permsList.push("allowSangria");
      if (roleConfig.allowCloseShift) permsList.push("allowCloseShift");
      if (roleConfig.allowViewReports) permsList.push("allowViewReports");
      if (roleConfig.allowOpenBalance) permsList.push("allowOpenBalance");
      if (roleConfig.allowRemoveProduct) permsList.push("allowRemoveProduct");
      if (roleConfig.allowResetEntirePDV) permsList.push("allowResetEntirePDV");
      if (roleConfig.allowReturn !== false) permsList.push("allowReturn");
      if (roleConfig.allowFiados !== false) permsList.push("allowFiados");
      if (roleConfig.allowGetCustomerContact !== false) permsList.push("allowGetCustomerContact");
      if (roleConfig.allowAddProduct !== false) permsList.push("allowAddProduct");
      return permsList;
    }
  }

  const isGerente = staff.role === "gerente";
  const permsList: string[] = [];
  if (isGerente) {
    if (pdvPermissions.allowDiscountGer) permsList.push("allowDiscount");
    if (pdvPermissions.allowEditPriceGer) permsList.push("allowEditPrice");
    if (pdvPermissions.allowVoidSaleGer) permsList.push("allowVoidSale");
    if (pdvPermissions.allowCashAdjustmentGer) { permsList.push("allowSuprimento"); permsList.push("allowSangria"); }
    if (pdvPermissions.allowCloseShiftGer) permsList.push("allowCloseShift");
    if (pdvPermissions.allowViewReportsGer) permsList.push("allowViewReports");
    if (pdvPermissions.allowCashAdjustmentGer) permsList.push("allowOpenBalance");
    if (pdvPermissions.allowRemoveProductGer) permsList.push("allowRemoveProduct");
    if (pdvPermissions.allowResetEntirePDVGer) permsList.push("allowResetEntirePDV");
    permsList.push("allowReturn");
    permsList.push("allowFiados");
    permsList.push("allowGetCustomerContact");
    permsList.push("allowAddProduct");
  } else {
    if (pdvPermissions.allowDiscountFunc) permsList.push("allowDiscount");
    if (pdvPermissions.allowEditPriceFunc) permsList.push("allowEditPrice");
    if (pdvPermissions.allowVoidSaleFunc) permsList.push("allowVoidSale");
    if (pdvPermissions.allowCashAdjustmentFunc) { permsList.push("allowSuprimento"); permsList.push("allowSangria"); }
    if (pdvPermissions.allowCloseShiftFunc) permsList.push("allowCloseShift");
    if (pdvPermissions.allowViewReportsFunc) permsList.push("allowViewReports");
    if (pdvPermissions.allowCashAdjustmentFunc) permsList.push("allowOpenBalance");
    if (pdvPermissions.allowRemoveProductFunc) permsList.push("allowRemoveProduct");
    if (pdvPermissions.allowResetEntirePDVFunc) permsList.push("allowResetEntirePDV");
    permsList.push("allowReturn");
    permsList.push("allowFiados");
    permsList.push("allowGetCustomerContact");
  }
  return permsList;
}

export interface PDVPermissions {
  allowDiscountFunc: boolean;
  maxDiscountFunc: number;
  allowDiscountGer: boolean;
  maxDiscountGer: number;

  allowRemoveProductFunc: boolean;
  allowRemoveProductGer: boolean;

  allowEditPriceFunc: boolean;
  allowEditPriceGer: boolean;

  allowCashAdjustmentFunc: boolean;
  allowCashAdjustmentGer: boolean;

  allowVoidSaleFunc: boolean;
  allowVoidSaleGer: boolean;

  allowCloseShiftFunc: boolean;
  allowCloseShiftGer: boolean;

  allowResetEntirePDVFunc: boolean;
  allowResetEntirePDVGer: boolean;

  allowViewReportsFunc: boolean;
  allowViewReportsGer: boolean;

  allowPermissionsFunc?: boolean;
  allowPermissionsGer?: boolean;
}

export const DEFAULT_PERMISSIONS: PDVPermissions = {
  allowDiscountFunc: true,
  maxDiscountFunc: 50,
  allowDiscountGer: true,
  maxDiscountGer: 100,

  allowRemoveProductFunc: false,
  allowRemoveProductGer: false,

  allowEditPriceFunc: false,
  allowEditPriceGer: true,

  allowCashAdjustmentFunc: false,
  allowCashAdjustmentGer: true,

  allowVoidSaleFunc: false,
  allowVoidSaleGer: true,

  allowCloseShiftFunc: true,
  allowCloseShiftGer: true,

  allowResetEntirePDVFunc: false,
  allowResetEntirePDVGer: false,

  allowViewReportsFunc: false,
  allowViewReportsGer: true,

  allowPermissionsFunc: false,
  allowPermissionsGer: true,
};

const DEFAULT_ROLE_PERMS_HELPER = (role: string): RolePermissions => ({
  allowDiscount: true,
  maxDiscount: role === "gerente" ? 100 : 50,
  allowEditPrice: role === "gerente",
  allowVoidSale: role === "gerente",
  allowSuprimento: role === "gerente" || role === "caixa",
  allowSangria: role === "gerente" || role === "caixa",
  allowCloseShift: true,
  allowViewReports: role === "gerente",
  allowOpenBalance: role === "gerente" || role === "caixa",
  allowRemoveProduct: role === "gerente",
  allowResetEntirePDV: role === "gerente",
  allowNotes: true,
  allowReceipts: true,
  allowAgenda: true,
  allowBrecho: true,
  allowSuper: true,
  allowEncartes: true,
  allowFinanceiro: role === "gerente",
  allowPDV: true,
  allowInventory: true,
  allowPermissions: role === "gerente",
  allowReturn: role === "gerente" || role === "caixa",
  allowFiados: role === "gerente" || role === "caixa",
  allowGetCustomerContact: true,
  allowAddProduct: role === "gerente"
});

const syncSystemConfigToPdvPermissions = (config: SystemConfig): PDVPermissions => {
  const caixa = config.caixa || DEFAULT_ROLE_PERMS_HELPER("caixa");
  const gerente = config.gerente || DEFAULT_ROLE_PERMS_HELPER("gerente");
  return {
    allowDiscountFunc: caixa.allowDiscount,
    maxDiscountFunc: caixa.maxDiscount ?? 5,
    allowDiscountGer: gerente.allowDiscount,
    maxDiscountGer: gerente.maxDiscount ?? 20,

    allowRemoveProductFunc: caixa.allowRemoveProduct,
    allowRemoveProductGer: gerente.allowRemoveProduct,

    allowEditPriceFunc: caixa.allowEditPrice,
    allowEditPriceGer: gerente.allowEditPrice,

    allowCashAdjustmentFunc: caixa.allowSuprimento || caixa.allowSangria,
    allowCashAdjustmentGer: gerente.allowSuprimento || gerente.allowSangria,

    allowVoidSaleFunc: caixa.allowVoidSale,
    allowVoidSaleGer: gerente.allowVoidSale,

    allowCloseShiftFunc: caixa.allowCloseShift,
    allowCloseShiftGer: gerente.allowCloseShift,

    allowResetEntirePDVFunc: caixa.allowResetEntirePDV || false,
    allowResetEntirePDVGer: gerente.allowResetEntirePDV || false,

    allowViewReportsFunc: caixa.allowViewReports,
    allowViewReportsGer: gerente.allowViewReports,

    allowPermissionsFunc: caixa.allowPermissions !== false,
    allowPermissionsGer: gerente.allowPermissions !== false,
  };
};

const updateSystemConfigFromPdvPermissionsKey = (
  currentConfig: SystemConfig,
  key: string,
  value: any
): SystemConfig => {
  const config = JSON.parse(JSON.stringify(currentConfig)) as SystemConfig;
  
  if (!config.caixa) config.caixa = DEFAULT_ROLE_PERMS_HELPER("caixa");
  if (!config.gerente) config.gerente = DEFAULT_ROLE_PERMS_HELPER("gerente");
  if (!config.vendedor) config.vendedor = DEFAULT_ROLE_PERMS_HELPER("vendedor");

  switch (key) {
    case "allowDiscountFunc":
      config.caixa.allowDiscount = !!value;
      break;
    case "maxDiscountFunc":
      config.caixa.maxDiscount = Number(value);
      break;
    case "allowDiscountGer":
      config.gerente.allowDiscount = !!value;
      break;
    case "maxDiscountGer":
      config.gerente.maxDiscount = Number(value);
      break;
    case "allowRemoveProductFunc":
      config.caixa.allowRemoveProduct = !!value;
      break;
    case "allowRemoveProductGer":
      config.gerente.allowRemoveProduct = !!value;
      break;
    case "allowEditPriceFunc":
      config.caixa.allowEditPrice = !!value;
      break;
    case "allowEditPriceGer":
      config.gerente.allowEditPrice = !!value;
      break;
    case "allowCashAdjustmentFunc":
      config.caixa.allowSuprimento = !!value;
      config.caixa.allowSangria = !!value;
      config.caixa.allowOpenBalance = !!value;
      break;
    case "allowCashAdjustmentGer":
      config.gerente.allowSuprimento = !!value;
      config.gerente.allowSangria = !!value;
      config.gerente.allowOpenBalance = !!value;
      break;
    case "allowVoidSaleFunc":
      config.caixa.allowVoidSale = !!value;
      break;
    case "allowVoidSaleGer":
      config.gerente.allowVoidSale = !!value;
      break;
    case "allowCloseShiftFunc":
      config.caixa.allowCloseShift = !!value;
      break;
    case "allowCloseShiftGer":
      config.gerente.allowCloseShift = !!value;
      break;
    case "allowResetEntirePDVFunc":
      config.caixa.allowResetEntirePDV = !!value;
      break;
    case "allowResetEntirePDVGer":
      config.gerente.allowResetEntirePDV = !!value;
      break;
    case "allowViewReportsFunc":
      config.caixa.allowViewReports = !!value;
      break;
    case "allowViewReportsGer":
      config.gerente.allowViewReports = !!value;
      break;
    case "allowPermissionsFunc":
      config.caixa.allowPermissions = !!value;
      break;
    case "allowPermissionsGer":
      config.gerente.allowPermissions = !!value;
      break;
  }

  return config;
};

