  const localHandleFirestoreError = (error: any, operationType: OperationType, path: string | null) => {
    const auth = getAuth();
    const errorMessage = error instanceof Error ? error.message : String(error);
    const errorCode = error?.code;

    const errInfo: FirestoreErrorInfo = {
      error: errorMessage,
      authInfo: {
        userId: auth.currentUser?.uid,
        email: auth.currentUser?.email,
        emailVerified: auth.currentUser?.emailVerified,
        isAnonymous: auth.currentUser?.isAnonymous,
        tenantId: auth.currentUser?.tenantId,
        providerInfo:
          auth.currentUser?.providerData?.map((provider) => ({
            providerId: provider.providerId,
            email: provider.email,
          })) || [],
      },
      operationType,
      path,
    };

    console.error(
      `Firestore Error [${errorCode || "unknown"}]: `,
      JSON.stringify(errInfo),
    );
  };

  // Real-time listener for Role-based Firestore permissions (with offline fallback)
  useEffect(() => {
    if (!isLoggedIn || !userId || userId === "guest_visitor" || !db) {
      try {
        const saved = localStorage.getItem("pdv_system_config");
        if (saved) {
          setSystemConfig(JSON.parse(saved));
        } else {
          setSystemConfig(null);
        }
      } catch {
        setSystemConfig(null);
      }
      return;
    }

    const auth = getAuth();
    let unsubscribeSnapshot: (() => void) | null = null;

    const unsubscribeAuth = auth.onAuthStateChanged((currentUser) => {
      if (unsubscribeSnapshot) {
        unsubscribeSnapshot();
        unsubscribeSnapshot = null;
      }

      if (currentUser && currentUser.uid === userId) {
        const docRef = doc(db, "configuracoes_sistema", userId);
        unsubscribeSnapshot = onSnapshot(docRef, async (docSnap) => {
          if (docSnap.exists()) {
            const data = docSnap.data() as SystemConfig;
            setSystemConfig(data);
            const syncedPerms = syncSystemConfigToPdvPermissions(data);
            setPdvPermissions(syncedPerms);
            localStorage.setItem("pdv_permissions", JSON.stringify(syncedPerms));
          } else {
            // Document does not exist, initialize and save it
            const initialConfig: SystemConfig = {
              userId: userId,
              caixa: DEFAULT_ROLE_PERMS_HELPER("caixa"),
              vendedor: DEFAULT_ROLE_PERMS_HELPER("vendedor"),
              gerente: DEFAULT_ROLE_PERMS_HELPER("gerente")
            };
            try {
              await setDoc(docRef, {
                ...initialConfig,
                createdAt: new Date().toISOString()
              });
              setSystemConfig(initialConfig);
              const syncedPerms = syncSystemConfigToPdvPermissions(initialConfig);
              setPdvPermissions(syncedPerms);
              localStorage.setItem("pdv_permissions", JSON.stringify(syncedPerms));
            } catch (err) {
              console.error("Erro ao inicializar permissões do Firestore:", err);
            }
          }
        }, (err) => {
          localHandleFirestoreError(err, OperationType.GET, `configuracoes_sistema/${userId}`);
        });
      } else {
        setSystemConfig(null);
      }
    });

    return () => {
      unsubscribeAuth();
      if (unsubscribeSnapshot) {
        unsubscribeSnapshot();
      }
    };
  }, [isLoggedIn, userId, db]);

