  const [auditLogs, setAuditLogs] = useState<any[]>([]);
  const [isLoadingAuditLogs, setIsLoadingAuditLogs] = useState<boolean>(false);

  const fetchAuditLogs = useCallback(async () => {
    if (!isLoggedIn || !userId || userId === "guest_visitor" || !db) {
      setIsLoadingAuditLogs(true);
      try {
        const savedLogs = localStorage.getItem("pdv_audit_logs");
        if (savedLogs) {
          const parsed = JSON.parse(savedLogs);
          parsed.sort((a: any, b: any) => {
            const timeA = a.timestamp ? new Date(a.timestamp).getTime() : 0;
            const timeB = b.timestamp ? new Date(b.timestamp).getTime() : 0;
            return timeB - timeA;
          });
          setAuditLogs(parsed.slice(0, 50));
        } else {
          setAuditLogs([]);
        }
      } catch (e) {
        console.error("Error loading offline audit logs:", e);
      } finally {
        setIsLoadingAuditLogs(false);
      }
      return;
    }
    setIsLoadingAuditLogs(true);
    try {
      const q = query(
        collection(db, "audit_logs"),
        where("userId", "==", userId),
        limit(150)
      );
      const querySnapshot = await getDocs(q);
      const logsList = querySnapshot.docs.map(doc => ({
        id: doc.id,
        ...doc.data()
      }));
      
      logsList.sort((a: any, b: any) => {
        const timeA = a.timestamp ? new Date(a.timestamp).getTime() : 0;
        const timeB = b.timestamp ? new Date(b.timestamp).getTime() : 0;
        return timeB - timeA;
      });
      
      setAuditLogs(logsList.slice(0, 50));
    } catch (e) {
      console.error("Error fetching audit logs:", e);
    } finally {
      setIsLoadingAuditLogs(false);
    }
  }, [isLoggedIn, userId, db]);

  const logRiskAction = useCallback(async (action: string, description: string, details?: any) => {
    let staffName = gestaoUserStaffName || "Não identificado";
    let staffRole = gestaoUserRole || "Não identificado";
    
    if (isOwnerMode) {
      staffName = "Proprietário";
      staffRole = "proprietario";
    }

    const newLog = {
      userId: userId || "guest_visitor",
      staffName,
      staffRole,
      action,
      description,
      timestamp: new Date().toISOString(),
      details: details || {}
    };

    // Store in localStorage
    try {
      const savedLogs = localStorage.getItem("pdv_audit_logs");
      const parsedLogs = savedLogs ? JSON.parse(savedLogs) : [];
      parsedLogs.push(newLog);
      localStorage.setItem("pdv_audit_logs", JSON.stringify(parsedLogs));
    } catch (e) {
      console.error("Error saving offline audit log:", e);
    }

    if (!isLoggedIn || !userId || userId === "guest_visitor" || !db) {
      console.log(`[Offline Audit Log] Success: ${action} - ${description}`);
      if (gestaoActiveTab === "permissoes") {
        fetchAuditLogs();
      }
      return;
    }
    
    try {
      const logsCollection = collection(db, "audit_logs");
      await addDoc(logsCollection, {
        userId,
        staffName,
        staffRole,
        action,
        description,
        timestamp: new Date().toISOString(),
        details: details || {}
      });
      console.log(`[Audit Log] Success: ${action} - ${description}`);
      if (gestaoActiveTab === "permissoes") {
        fetchAuditLogs();
      }
    } catch (e) {
      console.error("[Audit Log] Error writing audit log:", e);
    }
  }, [isLoggedIn, userId, db, gestaoUserStaffName, gestaoUserRole, isOwnerMode, gestaoActiveTab, fetchAuditLogs]);

