  // --- Real-time Daily Profit, Margin & Revenues Stats ---
  const getDailyProfitStats = () => {
    const today = new Date();
    
    // Filter all active (non-deleted) transactions of today
    const todaysTxs = transactions.filter(tx => {
      if (tx.isDeleted) return false;
      const txDate = new Date(tx.timestamp);
      return (
        txDate.getDate() === today.getDate() &&
        txDate.getMonth() === today.getMonth() &&
        txDate.getFullYear() === today.getFullYear()
      );
    });

    let faturamentoBruto = 0;
    let totalFees = 0;
    let totalCustoMercadoria = 0;
    let missingCostItemsCount = 0;
    let salesCount = 0;

    todaysTxs.forEach(tx => {
      if (tx.type === "entrada" && tx.category === "venda") {
        faturamentoBruto += tx.amount;
        salesCount++;

        // Calculate card/payment machine fees
        const rate = paymentRates[tx.paymentMethod] || 0;
        const fee = tx.feeAmount !== undefined ? tx.feeAmount : parseFloat(((tx.amount * rate) / 100).toFixed(2));
        totalFees += fee;

        // Calculate cost of goods sold (CMV)
        if (tx.items && tx.items.length > 0) {
          tx.items.forEach(item => {
            const match = activeProductsList.find(p => p.name.toUpperCase() === item.name.toUpperCase());
            const stockInfo = match ? productStockData[match.id] : null;
            const costPrice = stockInfo && stockInfo.costPrice !== undefined ? stockInfo.costPrice : 0;
            
            if (!stockInfo || stockInfo.costPrice === undefined) {
              missingCostItemsCount++;
            }
            
            totalCustoMercadoria += costPrice * item.quantity;
          });
        }
      }
    });

    const faturamentoLiquido = faturamentoBruto - totalFees;
    const lucroLiquidoReal = faturamentoLiquido - totalCustoMercadoria;
    const margemLucroPercent = faturamentoLiquido > 0 ? (lucroLiquidoReal / faturamentoLiquido) * 100 : 0;

    return {
      todaysTxs,
      faturamentoBruto,
      totalFees,
      faturamentoLiquido,
      totalCustoMercadoria,
      lucroLiquidoReal,
      margemLucroPercent,
      missingCostItemsCount,
      salesCount
    };
  };

