  const handleShareReconciliationToWhatsApp = (log: typeof reconciliationLogs[0]) => {
    let text = `⚖️ *CONCILIAÇÃO E BALANCEAMENTO DE CAIXA* ⚖️\n`;
    text += `🏢 *Segmento:* ${selectedNiche.toUpperCase().replace("_", " ")}\n`;
    text += `🕒 *Data do Fechamento:* ${log.date}\n`;
    text += `-----------------------------------------------\n\n`;

    text += `💰 *VALORES APURADOS:*\n`;
    text += `• 📈 Valor Esperado em Sistema: *${formatCurrency(log.expected)}*\n`;
    text += `• 💵 Valor Físico Real Contado: *${formatCurrency(log.counted)}*\n`;
    
    text += `\n📊 *DIVERGÊNCIA / RESULTADO:*\n`;
    if (log.status === "perfeito") {
      text += `✅ *STATUS: CAIXA PERFEITO & BALANCEADO!* 🎉\n`;
      text += `• Diferença: ${formatCurrency(0)} (Nenhuma divergência)\n`;
    } else if (log.status === "quebra") {
      text += `🚨 *STATUS: QUEBRA DE CAIXA! (Falta Dinheiro)* ⚠️\n`;
      text += `• Valor em Falta: *-${formatCurrency(Math.abs(log.diff))}*\n`;
      text += `• _Atenção: Houve perda de troco ou vendas não registradas!_\n`;
    } else {
      text += `💰 *STATUS: SOBRA DE CAIXA! (Dinheiro Extra)* ✨\n`;
      text += `• Valor Sobrando: *+${formatCurrency(log.diff)}*\n`;
      text += `• _Atenção: Verifique se algum valor foi inserido sem registro!_\n`;
    }

    // Add cash breakdown details if they exist and are non-zero
    const nonZeroBills = Object.entries(log.countedDetails || {}).filter(([_, qty]) => (Number(qty)) > 0);
    if (nonZeroBills.length > 0) {
      text += `\n🔢 *DETALHE DA CONTAGEM FÍSICA:*\n`;
      nonZeroBills.forEach(([value, qty]) => {
        const isCoin = parseFloat(value) < 2;
        text += `• ${qty}x ${isCoin ? "Moeda" : "Cédula"} de R$ ${parseFloat(value).toFixed(2).replace(".", ",")}\n`;
      });
    }

    text += `\n-----------------------------------------------\n`;
    text += `☁️ _Sincronizado automaticamente via nuvem._\n`;
    text += `📱 _Gerado direto do celular do estabelecimento via PDV Inteligente!_`;

    const url = `https://api.whatsapp.com/send?text=${encodeURIComponent(text)}`;
    window.open(url, "_blank");
    showNotification("Relatório de balanceamento enviado com sucesso via WhatsApp! ⚖️📲", "success");
  };

