                      // Save to cloud & localStorage
                      saveToLocalStorage(transactions, initialCash, customProducts, selectedNiche, productOverrides, customNiches, productStockData, panelOwnerPinInput, true, isCashRegisterOpen, staffPins, pdvPermissions);
                      pushToCloud(transactions, initialCash, customProducts, productOverrides, customNiches, productStockData, panelOwnerPinInput, true, reconciliationLogs, isCashRegisterOpen, staffPins, pdvPermissions);
                      
                      // Log to audit
                      logRiskAction("Alterar PIN Proprietário", `O Proprietário alterou o PIN principal de segurança do caixa.`);
                      
                      setPanelOwnerPinInput("");
                      setPanelOwnerPinConfirm("");
                      showNotification("PIN do Proprietário alterado com sucesso! 🔒👑", "success");
