                                  const costVal = (document.getElementById(`edit-stock-cost-${product.id}`) as HTMLInputElement)?.value || "";
                                  const qtyVal = (document.getElementById(`edit-stock-qty-${product.id}`) as HTMLInputElement)?.value || "";
                                  const minVal = (document.getElementById(`edit-stock-min-${product.id}`) as HTMLInputElement)?.value || "";
